"""Worked multilevel/shared dependency fixtures, independent of document order."""

from pathlib import Path

from tests.correlation_helpers import convert_documents, correlation_document, source_document


def documents(generate=False):
    raw = source_document()
    raw["id"] = "11111111-1111-1111-1111-111111111111"
    child = correlation_document("child", "event_count", [raw["id"]], condition={"gte": 2}, generate=generate)
    child["id"] = "22222222-2222-2222-2222-222222222222"
    middle = correlation_document(
        "middle", "value_count", ["child"], field="EventCount", condition={"gte": 1}, generate=generate
    )
    middle["id"] = "33333333-3333-3333-3333-333333333333"
    parent = correlation_document("parent", "temporal", [middle["id"], child["id"], "direct"], generate=generate)
    sibling = correlation_document("sibling", "event_count", ["child"], condition={"gte": 2}, generate=generate)
    return [
        parent,
        source_document("unrelated", marker="other"),
        middle,
        source_document("direct", marker="direct", product="network"),
        sibling,
        child,
        raw,
    ]


def fixtures():
    result = {}
    for generate in (False, True):
        queries = convert_documents(documents(generate))
        parent = next(query for query in queries if ", RuleCount" in query)
        # Child summaries at 12:01 (count 2) and 12:06 (count 2), both
        # included at the exact five-minute endpoint. The direct match at
        # 12:02 establishes the first all-three-type result. 12:07 includes
        # only the 12:06 child/middle and the direct match at its endpoint.
        result[f"dependency_order_{'generate' if generate else 'suppressed'}.kql"] = (
            "// Generated by dependency_order.py through public Sigma parsing and conversion.\n"
            "// PASS: zero summary multiset differences. Runtime evidence: RUNTIME.md.\n"
            "let Events = datatable(Timestamp:datetime, Host:string, Marker:string) [\n"
            'datetime(2026-01-01T12:00:00Z), "host", "match",\n'
            'datetime(2026-01-01T12:01:00Z), "host", "match",\n'
            'datetime(2026-01-01T12:06:00Z), "host", "match",\n'
            'datetime(2026-01-01T12:02:00Z), "host", "other"\n];\n'
            "let NetworkEvents = datatable(Timestamp:datetime, Host:string, Marker:string) [\n"
            'datetime(2026-01-01T12:02:00Z), "host", "direct",\n'
            'datetime(2026-01-01T12:07:00Z), "host", "direct"\n];\n'
            "let Actual = () {\n" + parent + "\n};\n"
            "let Expected = datatable(WindowEnd:datetime, Host:string, RuleCount:long) [\n"
            'datetime(2026-01-01T12:02:00Z), "host", 3,\n'
            'datetime(2026-01-01T12:06:00Z), "host", 3,\n'
            'datetime(2026-01-01T12:07:00Z), "host", 3\n]\n'
            "| extend WindowStart = WindowEnd - 5m;\n"
            "union (Actual() | extend Host = tostring(Host), Delta = 1), (Expected | extend Delta = -1)\n"
            "| summarize Delta = sum(Delta) by WindowStart, WindowEnd, Host, RuleCount\n"
            "| where Delta != 0\n"
        )
    return result


if __name__ == "__main__":
    for name, query in fixtures().items():
        Path(__file__).with_name(name).write_text(query)
